npx --yes --package @playwright/cli playwright-cli eval "() => { const h1 = document.querySelector('h1'); const chain = []; let n = h1; while (n && n !== document.body) { const r = n.getBoundingClientRect(); const cs = getComputedStyle(n); chain.push(n.tagName + '.' + String(n.className && n.className.baseVal !== undefined ? n.className.baseVal : n.className).slice(0,60) + ' l=' + Math.round(r.left) + ' w=' + Math.round(r.width) + ' disp=' + cs.display + ' pad=' + cs.padding + ' ml=' + cs.marginLeft); n = n.parentElement; } return chain.join(' < '); }" > $null 2>&1
